import{_ as r,l as i,o as e,c as s,v as o,p as d,x as l,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"溢出与重物化","description":"","frontmatter":{"title":"溢出与重物化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spill-remat.md","filePath":"cs/spill-remat.md","lastUpdated":1789023840000}'),h={name:"cs/spill-remat.md"};function m(E,a,_,u,B,A){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="溢出与重物化" tabindex="-1">溢出与重物化 <a class="header-anchor" href="#溢出与重物化" aria-label="Permalink to &quot;溢出与重物化&quot;">​</a></h1><div class="epigraph"><p>颜色不够就把虚拟寄存器存到栈槽；能从立即数或不变地址再算出来的值，宁可重物化，也不占一条活过调用的槽。</p><footer>—— 据 Chaitin, Register Allocation and Spilling, 1982；Briggs, Cooper and Torczon, Rematerialization, 1992 整理</footer></div><p>上一课<a href="/cs/regalloc-color">寄存器分配着色</a>建冲突图、启发式 \\(K\\)-着色，失败则溢出再写 IR。本课不重做简化压栈。缺口是<strong>溢出之后写什么指令</strong>：<code>store</code>/<code>load</code> 到帧槽，以及 Briggs 的重物化——常量、全局地址、<code>sp</code> 相对的不变计算不必 round-trip 内存。窥孔下一课再清 <code>move</code> 垃圾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色挑出溢出候选（度数高、跨度长、在循环外代价低）。朴素：在每次使用前 load、定值后 store。槽位按帧布局编号，<a href="/cs/calling-convention-stack">调用约定</a> 的帧指针已有直觉，ABI 课再钉对齐。缺口是代价：load 延迟与占用，可能让调度与活跃一起变坏，故分配–溢出–再着色循环。</p><p>重物化：若值的定义是 <code>li t, 4</code> 或 <code>lui+addi</code> 形成的池常量，使用处重新执行那几条便宜指令，不分配槽、不延长内存相关。判断：定义无副作用、操作数随时可再得（立即数、日历寄存器）。循环里重物化 vs 在循环外 load 一次，用简单代价比。</p><h3 id="溢出不是-malloc" tabindex="-1">溢出不是 malloc <a class="header-anchor" href="#溢出不是-malloc" aria-label="Permalink to &quot;溢出不是 malloc&quot;">​</a></h3><p>槽在当前帧，随调用生灭。不要把 spill 写成堆对象。callee-save 的保存也是一种「溢出到序言」，但是 ABI 合同，不是着色失败。</p><p><span class="marginnote">Chaitin 1982 溢出。Briggs et al. 1992（PLDI）rematerialization。乐观着色减少「其实着得上却被溢出」的候选。本课两者都要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对溢出名：拆活跃区间或整名溢出。插入访问。对可重物化名：在使用处复制定义指令，删原跨区间的冲突边。更新 IR 后重算活跃与冲突图，再着色。</p>',11)),(e(),d(p,null,{default:l(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E7%9D%80%E8%89%B2%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20COST%5B%22%E9%80%89%E6%BA%A2%E5%87%BA%E5%90%8D%22%5D%0A%20%20COST%20--%3E%20MEM%5B%22store%2Fload%20%E6%A7%BD%22%5D%0A%20%20COST%20--%3E%20REM%5B%22%E9%87%8D%E7%89%A9%E5%8C%96%E5%BB%89%E4%BB%B7%E5%AE%9A%E4%B9%89%22%5D%0A%20%20MEM%20--%3E%20RE%5B%22%E5%86%8D%E7%9D%80%E8%89%B2%22%5D%0A%20%20REM%20--%3E%20RE%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>无限循环：每次必须减少「无法着色的压力」，或放大 \\(K\\) 的有效（拆区间）。实现设轮数上限。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>溢出增加访存，<a href="/cs/locality-principle">Cache</a> 变差，分配器不模拟层次。重物化增加指令条数、可能加长调度关键路径，用加法延迟对比 load 延迟。φ 应在溢出前拆掉，否则槽与前驱 <code>move</code> 纠缠。</p><p>不要溢出 <code>sp</code> 本身。不要把条件执行的定值重物化到必经路上而不顾控制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写窥孔模式、不输出目标文件。后课默认：函数体是物理寄存器加必要的 spill/re-mat。短窗口代数简化是窥孔的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>溢出：帧槽 round-trip；重物化：再执行廉价定义。</li><li>二者都改变 IR，需再着色。</li><li>槽不是堆；合同保存不是失败溢出。</li><li>出处：Chaitin, 1982；Briggs, Cooper and Torczon, 1992。</li></ul>',8))])}const g=r(h,[["render",m]]);export{T as __pageData,g as default};
